/**
 * Zieht Vor- und Nachnamen zu einer Nation.
 * Unbekannte Nationen fallen auf 'DE' zurück.
 */
export function pickName(rng, nat) {
  const key = FIRST_NAMES[nat] && LAST_NAMES[nat] ? nat : 'DE';
  return {
    firstName: rng.pick(FIRST_NAMES[key]),
    lastName: rng.pick(LAST_NAMES[key])
  };
}

/**
 * Zieht eine Nation aus einem gewichteten Pool ([{ nat, weight }]).
 * Ohne Pool wird der internationale Transfermarkt benutzt.
 */
export function pickNation(rng, pool) {
  const list = Array.isArray(pool) && pool.length ? pool : NATION_POOL_TRANSFER;
  const entry = rng.pickWeighted(list, (it) => (it && it.weight > 0 ? it.weight : 1));
  const nat = entry && entry.nat ? entry.nat : 'DE';
  return FIRST_NAMES[nat] ? nat : 'DE';
}
